(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["is"] = {"ui":{"skip":"Fara beint í efnið","back":"← Til baka í AI-gile","lang.button":"Tungumál: {name}","lang.dialog":"Veldu tungumál","lang.search":"Leita að tungumáli","lang.none":"Ekkert tungumál passar","lang.notYet":"{name} er ekki þýtt enn","theme.aria":"Skipta á milli ljóss og dökks þema","theme.toLight":"Skipta yfir í ljóst þema","theme.toDark":"Skipta yfir í dökkt þema","words.underline":"Undirstrika þessi orð á síðunni","words.underlineHelp":"Færðu bendilinn yfir orð með punktalínu eða pikkaðu á það til að sjá hvað það þýðir.","index.title":"AI-gile: gervigreindarteymið þitt á einni töflu","index.description":"AI-gile er kanban-tafla fyrir gervigreindarteymi sem forrita. Þau vinna meðan þú sefur og þú færð einn stuttan bunka af hlutum til að ákveða, prófa og samþykkja.","hero.logoAlt":"Táknmynd AI-gile töflunnar","hero.h1.html":"Gervigreindarteymið þitt á einni&nbsp;töflu.","hero.alpha":"🐣 Lokuð forútgáfa","hero.alphaTitle":"Snemma og ókláruð: takk fyrir að prófa!","hero.lede":"Þau smíða meðan þú sefur. Þú vaknar við einn stuttan bunka: nokkrar spurningar, nokkra hluti til að prófa, einn eða tvo fjólubláa demanta. Smella, samþykkja og aftur í kaffið.","dl.windows":"Windows-forrit","dl.browser":"Keyra í vafranum","dl.soon":"Kemur bráðum","dl.notify":"🔔 Láttu mig vita þegar opnað er","dl.notifySmall":"Alfa eða beta","hero.secondary":"Lipur vinna, en teymið þarf aldrei standandi kaffifund. (Þau halda samt fundi.)","pitch.h2":"AI-gile í eins mörgum orðum og þú vilt","pitch.lede":"Veldu lengd, frá einu orði upp í 144. Hver lengd er sín eigin lýsing, skrifuð fyrir þá stærð. Dragðu sleðann eða notaðu örvatakkana.","pitch.rangeLabel":"Lengd í orðum","pitch.dice":"🎲 önnur útgáfa","pitch.words.one":"{n} orð","pitch.words.other":"{n} orð","pitch.letters.one":"{n} bókstafur","pitch.letters.other":"{n} bókstafir","pitch.chars.one":"{n} tákn","pitch.chars.other":"{n} tákn","count.line.html.one":"{n} spjald á töflunni núna","count.line.html.other":"{n} spjöld á töflunni núna","features.aria":"Hvað það gerir","f.pile.h":"Einn bunki fyrir þig","f.pile.html":"<b>Fyrir þig</b> geymir allt sem bíður eftir þér, úr öllum verkefnum: spurningar, hluti til að prófa og verk sem aðeins manneskja getur gert. Biðröðin segir hvað er næst og hve lengi það tekur.","f.sleep.h":"Teymi sem vinna meðan þú sefur","f.sleep.p":"Hvert verkefni hefur leiðtoga og teymi gervigreindarfulltrúa. Skrifaðu athugasemd við spjald og teymið vaknar, vinnur verkið og skilar því með skrefum sem þreytt manneskja getur fylgt.","f.tester.h":"Gervigreindarprófari athugar fyrst","f.tester.p":"Áður en nokkuð berst til þín fylgir prófari skrefunum í afriti af forritinu og sýnir hvað hann sá, með skjámynd. Flettu í gegnum það sem stóðst og samþykktu með einum smelli.","f.proof.h":"Sönnun, ekki loforð","f.proof.p":"Hver afhending sýnir hvað breyttist: skrárnar, muninn og skjámyndirnar. Engin þörf á að opna hvert forrit til að sjá hvort verkinu sé lokið.","f.chat.h":"Spjallaðu við leiðtogana þína","f.chat.p":"Hliðarstika í anda Discord: eitt tákn fyrir hvert verkefni og fjólubláir demantar fyrir það sem þarfnast þín. Sendu leiðtoga hugmynd; hann breytir henni í spjöld og áætlun, með ✅ Áfram-hnappi.","f.tidy.h":"Heldur sér snyrtilegri","f.tidy.p":"Skyld spjöld renna saman í eitt, ruglingslegir titlar eru lagaðir og táknatalning heldur kóðanum mjóum. Færri hluti til að skipta á milli og minna að hugsa um.","f.private.h":"Þín eigin, á þinni tölvu","f.private.li1":"Taflan keyrir á þinni eigin vél og svarar aðeins þér.","f.private.li2":"Einkaskilaboð milli fólks eru dulkóðuð frá enda til enda.","f.private.li3":"Engir aðgangar, engir rekjarar, engar vefkökur.","f.lang.h":"Á þínu tungumáli","f.lang.p":"Yfir 120 tungumál, frá hollensku, velsku og japönsku til sjóræningjamáls, Yoda-máls og klingonsku, með fljótlegum rofa aftur yfir í ensku fyrir forritaraorðin.","tl.aria":"Tímalína frá fyrsta samtali að vegvísinum","tl.h2":"Frá fyrsta spjalli að því sem er næst","tl.lede":"Raunverulegar dagsetningar og tímar, í þínu eigin tímabelti. Eftir daginn í dag er þetta áætlun og engar dagsetningar eru lofaðar.","tl.today":"Í dag","tl.planned":"áætlað","tl.cards.one":"{n} spjald","tl.cards.other":"{n} spjöld","join.h2":"Vertu með","join.lede":"AI-gile er smíðað af einni lítilli manneskju og fjölda þolinmóðra fulltrúa. Það er lokað enn sem komið er, í lokaðri alfa með vinum. Viltu fá að prófa þegar það opnast?","join.btn":"Skrá áhuga","join.small":"Við sendum þér póst, ekkert annað","footer.tag":"AI-gile. Engir rekjarar, engar vefkökur, ekkert standandi kaffi.","footer.licence":"Fyrirtækjaleyfi","footer.status":"Staða","footer.privacy":"Hvað við geymum","form.sending":"Sendi…","form.failed":"Þetta tókst ekki: reyndu aftur seinna.","form.offline":"Náði ekki sambandi við AI-gile: reyndu aftur seinna.","form.keep":"Við notum þetta aðeins til að svara þér og eyðum því svo. Engir rekjarar, engar vefkökur.","form.keepLink":"Hvað við geymum","interest.title":"AI-gile: láttu mig vita þegar alfan opnast","interest.description":"Skildu eftir netfangið þitt til að heyra hvenær lokuð alfa eða beta AI-gile opnast.","interest.h1":"🔔 Láttu mig vita þegar opnað er","interest.lede":"AI-gile er í lokaðri forútgáfu. Skildu eftir netfangið þitt og við skrifum einu sinni, þegar pláss er fyrir þig.","interest.email":"Netfangið þitt","interest.which":"Hvaða prófun?","interest.alpha":"Lokuð alfa: snemma, hrjúf, miklar breytingar","interest.beta":"Beta: stöðugri, seinna","interest.both":"Hvort sem er, það sem kemur á undan","interest.submit":"Setjið mig á listann","interest.thanks":"Takk! Þú ert á listanum.","licence.title":"AI-gile: fyrirtækjaleyfi","licence.description":"Notarðu AI-gile í fyrirtækinu þínu? Sæktu um ókeypis fyrirtækjaleyfi.","licence.h1":"📜 Fyrirtækjaleyfi","licence.lede":"Notarðu AI-gile í vinnunni? Segðu okkur hver þú ert og hvað þú gerir. Ef það gerir eitthvert gagn er leyfið ókeypis.","licence.company":"Fyrirtæki","licence.website":"Vefsíða","licence.what":"Hvað þú gerir","licence.how":"Hvernig það hjálpar heiminum","licence.email":"Netfang","licence.submit":"Sækja um","licence.thanks":"Takk! Við svörum í tölvupósti.","status.title":"Staða AI-gile","status.h1":"Staða AI-gile","status.quiet":"Allt með kyrrum kjörum","status.intro":"Virkar AI-gile núna? Þessi síða athugar vefsíðuna, deilingu taflna, símtöl og niðurhalið á 5 mínútna fresti.","status.up":"Virkar (svaraði á {ms} ms)","status.slow":"Svaraði ekki síðustu athugun, reyni aftur","status.down":"Niðri: svaraði hvorugri af síðustu tveimur athugunum","status.svc.web":"Vefsíða","status.svc.web.offers":"Þessi síða: hvað AI-gile er, og áhugaskráningin","status.svc.boards":"Deiling taflna","status.svc.boards.offers":"Opinberar töflur, skilaboð milli vina og boð","status.svc.calls":"Símtöl","status.svc.calls.offers":"Tal, mynd og skjádeiling í AI-gile","status.svc.download":"Niðurhal","status.svc.download.offers":"Windows-uppsetningarforritið og boðstenglar","status.checking":"Athuga…","status.offline":"Næ ekki sambandi við stöðuþjónustuna núna (reyni aftur)","status.updated":"uppfært {ago}","status.justNow":"rétt í þessu","status.min":"fyrir {n} mín.","status.hours":"fyrir {n} klst.","status.days":"fyrir {n} d.","privacy.title":"AI-gile: hvað við geymum","privacy.h1":"Hvað við geymum","privacy.lede":"Í stuttu máli: aðeins það sem þú sendir okkur, og ekki lengi.","privacy.only":"Aðeins það sem þú sendir okkur: það sem þú skrifar í eyðublað, eins og netfangið þitt. Ekkert annað um þig.","privacy.sealed":"Það er innsiglað svo þjónninn okkar geti ekki lesið það: í vafranum þínum áður en það fer af stað (í eldri vafra, um leið og það berst). Aðeins okkar eigin tafla getur opnað það.","privacy.server":"Því er eytt af þjóninum um leið og það berst á töfluna okkar. Öllu sem er þar enn eftir 30 daga er eytt hvort sem er.","privacy.board":"Við geymum það á töflunni okkar aðeins þar til við höfum svarað þér, og eyðum því þá þar líka.","privacy.none":"Engir rekjarar, engar vefkökur, engar greiningar.","privacy.local":"Tungumálið þitt og val á ljósu eða dökku útliti verða eftir í þínum eigin vafra. Þau eru aldrei send til okkar.","privacy.ask":"Viltu að því sé eytt fyrr? Svaraðu tölvupóstinum okkar og segðu það.","live.h2":"Fylgstu með smíðinni, í beinni","live.caption":"Hvert spjald er falið: þú sérð lögun verksins, ekki orðin.","live.watching.one":"í beinni: {n} fylgist með","live.watching.other":"í beinni: {n} fylgjast með","live.last.now":"Síðasta spjald var fært rétt í þessu","live.last.min.one":"Síðasta spjald var fært fyrir {n} mínútu","live.last.min.other":"Síðasta spjald var fært fyrir {n} mínútum","live.last.hour.one":"Síðasta spjald var fært fyrir {n} klukkustund","live.last.hour.other":"Síðasta spjald var fært fyrir {n} klukkustundum","live.last.day.one":"Síðasta spjald var fært fyrir {n} degi","live.last.day.other":"Síðasta spjald var fært fyrir {n} dögum","live.offline":"Beina taflan tekur sér smá pásu. Kíktu aftur fljótlega.","live.cols":"Backlog|Á dagskrá|Í vinnslu|Teymið yfirfer|Fyrir þig að prófa|Fyrir teymið|Lokið"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Vélmenni.","Úthlutað."]},{"n":2,"texts":["Vélmenna-kanban, ókeypis.","Fulltrúar, skipulagðir.","Hugmyndir, smíðaðar."]},{"n":3,"texts":["Kanban fyrir vélmenni.","Hugmyndir verða eiginleikar.","Ókeypis fulltrúa-kanban."]},{"n":5,"texts":["Kanban-tafla sem fulltrúar reka.","Þú skrifar spjöld. Þau smíða.","Ókeypis, staðbundið, prófað og pínu kjánalegt."]},{"n":8,"texts":["Ókeypis kanban-tafla þar sem gervigreindarfulltrúar vinna.","Skrifaðu hugmynd. Þau smíða hana. Þú samþykkir.","Lipur vinna fyrir eina manneskju og mörg þolinmóð vélmenni."]},{"n":13,"texts":["Kanban-tafla á tölvunni þinni þar sem gervigreindarfulltrúar taka spjöldin að sér.","Skrifaðu hugmynd. Teymi fulltrúa smíðar hana. Prófari athugar hana áður en þú sérð hana.","Ókeypis, engir aðgangar, engir rekjarar: tafla, nokkur vélmenni og þú ræður ferðinni."]},{"n":21,"texts":["AI-gile er kanban-tafla til að vinna með gervigreindarfulltrúum sem forrita. Þeir taka spjöldin að sér; þú prófar þau og samþykkir.","Hvert verkefni fær leiðtoga og teymi gervigreindarfulltrúa. Skrifaðu athugasemd við hvaða spjald sem er og teymið tekur til starfa.","Ókeypis, persónuleg verkefnatafla sem keyrir á þinni eigin tölvu. Verkamennirnir eru vélmenni. Sá sem segir já ert þú."]},{"n":34,"texts":["Þú setur hugmyndir á töflu. Teymi gervigreindarfulltrúa breytir þeim í virka eiginleika, prófar þá og skilar þeim til baka með skrefum til að prófa. Ekkert telst búið fyrr en þú segir það.","AI-gile er heimasmíðuð kanban-tafla sem Rich bjó til með mikilli hjálp frá fulltrúunum sem hún stýrir nú. Hún er ókeypis, keyrir á tölvunni þinni og er deilt með vinum en ekki seld.","Hugsaðu þér venjulega kanban-töflu með dálkum frá Backlog til Lokið, nema að spjöldin eru tekin að sér af gervigreindarfulltrúum. Þeir segja frá framvindu, spyrja þegar þeir festast og bíða alltaf eftir þínu samþykki."]},{"n":55,"texts":["AI-gile er kanban-tafla þar sem teymið er skipað gervigreindarfulltrúum. Hvert verkefni hefur leiðtoga sem skipuleggur vinnuna og hjálparmenn sem smíða. Þegar eiginleiki er tilbúinn prófar gervigreindarprófari hann og tekur skjámynd, svo lendir hann í þínum bunka. Samþykktu hann eða skrifaðu athugasemd og þeir vinna hann upp á nýtt.","Þetta byrjaði sem leið einnar manneskju til að halda utan um fjölda gervigreindarforritunarlota í einu og óx í almennilega töflu. Hún keyrir á þinni vél, krefst engra aðganga og hefur enga rekjara. Hún er ókeypis fyrir vini og forvitna. Hún er líka ókláruð, svo búast má við hrjúfum köntum og óvæntum uppákomum.","Hér er heiðarlega útgáfan. Þú þarft enn að eiga hugmyndirnar og enn að yfirfara niðurstöðurnar. AI-gile sér um allt þar á milli: raðar spjöldunum, vekur réttan fulltrúa þegar þú skrifar athugasemd, sýnir nákvæmlega hvað breyttist og safnar öllu saman í einn stuttan bunka handa þér."]},{"n":89,"texts":["AI-gile er ókeypis kanban-tafla sem þú keyrir á þinni eigin tölvu. Í stað fólks hefur hvert verkefni teymi gervigreindarfulltrúa: leiðtoga sem breytir hugmyndunum þínum í spjöld og áætlun, og hjálparmenn sem taka spjöldin að sér í forgangsröð. Þegar eitthvað er smíðað fylgir gervigreindarprófari prófunarskrefunum og sýnir þér það sem hann sá. Svo bíður það í einum bunka sem heitir Fyrir þig. Þú samþykkir það, eða skrifar athugasemd og teymið reynir aftur. Ekkert kemst nokkurn tíma í Lokið án þín.","Nokkrir eiginleikar sem þú bjóst kannski ekki við. Næturvakt heldur Á dagskrá fullum meðan þú sefur og velur spjöld sem þurfa ekkert svar frá þér. Teljari sýnir hve mikið fulltrúarnir hafa notað í dag og í þessari viku, og No Token Mode segir þeim að hætta að eyða. Þú getur sent vinum skilaboð og einkaskilaboð eru dulkóðuð frá enda til enda. Taflan talar um 120 tungumál, þar á meðal hollensku, flæmsku, sjóræningjamál og klingonsku. Ekkert af þessu kostar krónu og enginn er að reyna að selja þér það.","AI-gile er lítið, persónulegt verkefni en ekki fyrirtæki. Rich vildi sinna nokkrum gervigreindarforritunarverkefnum án þess að opna hvert forrit til að athuga með þau, svo hann og fulltrúarnir smíðuðu töflu fyrir það og notuðu hana svo til að smíða afganginn af sjálfri sér. Hún er í lokaðri forútgáfu, sem þýðir að hún virkar, að mestu, fyrir fáeina vini. Hér er engin verðskrá, ekkert fréttabréf og engin vaxtaráætlun. Ef þetta hljómar gagnlegt geturðu beðið um að fá að prófa þegar hún opnast aðeins meira."]},{"n":144,"texts":["AI-gile er kanban-tafla fyrir eina manneskju og fjölda gervigreindarfulltrúa. Hún keyrir á þinni eigin tölvu og er alveg ókeypis. Þú bætir við verkefnum og hvert verkefni fær leiðtoga og lítið teymi. Þú spjallar við leiðtogann, svolítið eins og á Discord, og lýsir hugmynd; leiðtoginn breytir henni í spjöld og áætlun og bíður svo eftir að þú ýtir á Áfram. Teymið vinnur sig í gegnum spjöldin í forgangsröð og notar einfalt skipanaviðmót sem er gert fyrir mállíkön. Áður en nokkuð kemur aftur til þín fylgir gervigreindarprófari skrefunum í afriti af forritinu og hengir við skjámynd. Fullunnið verk lendir í bunkanum þínum með breyttu skrárnar og muninn. Þú samþykkir það, eða skrifar athugasemd og teymið vaknar og reynir aftur. Aðeins þú getur fært spjald í Lokið.","Dagur með AI-gile, nokkurn veginn. Að kvöldi skrifarðu nokkrar athugasemdir: þessi hnappur er á röngum stað, þessum lista þarf að raða, gætum við fengið dökkt þema. Þú ferð að sofa. Fulltrúarnir lesa athugasemdirnar, gera breytingarnar, prófa þær og skila þeim til þín. Ef Á dagskrá tæmist fyllir næturvaktin hana úr Backlog með spjöldum sem þurfa ekkert svar frá þér. Að morgni er einn stuttur bunki: nokkrar spurningar og nokkrir hlutir til að prófa, hver með skrefum sem syfjuð manneskja getur fylgt og skjámynd af því að það virkar. Þú smellir þig í gegnum þetta, samþykkir það sem er gott og sendir restina til baka. Teljari sýnir hvað þetta kostaði og No Token Mode er til staðar fyrir sparsamar vikur. Svo færðu þér morgunmat, sem fulltrúarnir geta ekki hjálpað við enn.","Fyrst, hvað AI-gile er ekki. Það er ekki sprotafyrirtæki, það er ekki til sölu og enginn safnar gögnunum þínum. Það er ókeypis tafla sem keyrir á tölvunni þinni, án aðganga, án rekjara og án vefkakna. Það sem það er: einn snyrtilegur staður til að sjá öll gervigreindarforritunarverkefni í einu, þar sem teymi fulltrúa vinnur spjöldin og þú tekur ákvarðanirnar. Það steypir skyldum spjöldum saman, lagar ruglingslega titla og fylgist með að kóðinn haldist mjór. Það talar um 120 tungumál, frá hollensku og flæmsku til sjóræningjamáls og klingonsku. Vinir geta sent hver öðrum skilaboð, í einrúmi og dulkóðuð. Það var smíðað af Rich og fjölda þolinmóðra fulltrúa, mest með því að nota sjálft sig. Það er í lokaðri forútgáfu og því hrjúft sums staðar. Ef þetta hljómar skemmtilega, biddu kurteislega og þú gætir komist snemma inn."]}],"quips":{"1":"Eitt orð. Djarft. Kannski of djarft.","3":"Þrjú orð. Nú þegar heiðarlegri en flestar vörusíður.","8":"Átta orð. Samt styttra en standandi fundur.","21":"Lengdirnar eru reyndar sögupunktar. Að sjálfsögðu.","55":"Fimmtíu og fimm orð. Tvö spjöld kláruðust meðan þú last þetta.","144":"Þetta er það langa. Það er enginn 233. Fulltrúarnir eru farnir að sofa."}},"timeline":{"first-idea.name":"Fyrsta hugmyndin","first-idea.line":"Fyrsta samtalið, áður en nokkur kóði var til.","first-board.name":"Fyrsta taflan","first-board.line":"Tafla sem heldur utan um eigin smíði: spjöld, dálkar, draga og sleppa, verkefni.","team-roles.name":"Teymi og hlutverk","team-roles.line":"Prófílar fulltrúa, teymissniðmát, svæði og hver gerir hvað.","install.name":"Uppsetning og útgáfur","install.line":"Zip-skrá sem vinur getur sett upp, sjálfvirkar uppfærslur, rásir og afturköllun.","usage-saver.name":"Notkunarsparnaður","usage-saver.line":"Mæla hvað keyrslur kosta, halda kóðanum mjóum og spara kvótann.","friends.name":"Vinir og deiling","friends.line":"Einkaskilaboð, dulkóðuð miðlun, boð, hlutverk og sameiginleg verkefni.","languages.name":"Tungumál","languages.line":"Allir skjátextar í tungumálaskrá, fyrst hollenska og flæmska.","ai-tester.name":"Gervigreindarprófari","ai-tester.line":"Prófari athugar hverja afhendingu fyrst og sýnir hvað hann sá.","website.name":"Vefsíðan","website.line":"aigile.lol, kynningarsíðan og þessi tímalína.","streaming.name":"Spjall og streymi","streaming.line":"Discord, Twitch, OBS, streymisham, GIF og emoji.","no-ai.name":"Útgáfa án gervigreindar","no-ai.line":"Tafla fyrir fólk sem forritar án gervigreindar, og opinberar töflur.","night-watch.name":"Næturvaktin","night-watch.line":"Næturvörður og Scrum-meistari halda teymunum við efnið meðan þú sefur.","p-more.name":"Allt hitt","p-more.line":"Smærri hugmyndir sem bíða enn eftir röðinni.","p-android.name":"Sími og Android","p-android.line":"Náðu í töfluna úr síma, svo í sérsmíðað Android-forrit.","p-release.name":"Alfa og lengra","p-release.line":"Lokuð alfa, svo opna vefsíðan, svo beta.","p-languages.name":"Fleiri tungumál","p-languages.line":"Yfir hundrað tungumál og niðurdýfingarhamur fyrir nemendur.","p-engines.name":"Fleiri gervigreindarvélar","p-engines.line":"Veldu Claude, Codex eða Gemini fyrir hvern fulltrúa.","p-pro.name":"Fagleg vinnubrögð","p-pro.line":"Áhættumerki, samrunahlið, atvikaspjöld og öryggisgrindur.","p-self.name":"Hugsað um þig","p-self.line":"Þreytuhamur, áminningar um sjálfsumönnun og 4:20.","p-servers.name":"Þjónar og stækkun","p-servers.line":"Altækar þjónastillingar, hlutverk og áætlun fyrir vöxt.","p-livestream.name":"Streymisviðbætur","p-livestream.line":"Twitch-spjall, sérsniðin emoji og opin beint-sýn."},"words":{"button":"📖 Forritaraorð","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Leita að orði…","none":"Ekkert orð passar við það.","close":"Loka","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Kóðamappa verkefnisins með allri sögu sinni af commits, oftast líka geymd á GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Sérstök vinnulína í kóðanum, svo hægt sé að gera breytingar án þess að snerta aðalútgáfuna.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Vistuð skyndimynd af kóðanum með stuttri athugasemd um hvað breyttist. Alltaf er hægt að snúa aftur til hennar.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Að senda vistaðar skyndimyndir (commits) úr þessari tölvu upp á GitHub, svo þær séu afritaðar og öðrum aðgengilegar."},{"id":"merge","g":"build","word":"Merge","text":"Að sameina breytingar úr branch aftur við aðalútgáfuna."},{"id":"pr","g":"build","word":"Pull request","text":"Beiðni um að breytingar úr branch séu yfirfarnar og sameinaðar aðalútgáfunni.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Að taka til í kóðanum án þess að breyta því sem hann gerir: minni skrár, skýrari nöfn, minni endurtekning."},{"id":"bug","g":"build","word":"Villa","text":"Eitthvað sem virkar ekki eins og það á að gera.","also":["villa","villu","villur","villum","villna","villurnar","bugs","bug"]},{"id":"test","g":"build","word":"Prófun","text":"Að prófa fullunna vinnu til að athuga hvort hún geri það sem beðið var um, áður en hún er samþykkt.","also":["prófa","prófun","prófunar","prófir","prófanir","prófana","prófunum","próf","test","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Að setja nýja útgáfu í loftið, til dæmis á þjón þar sem fólk notar hana."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Hugmyndir og vinna sem ekki er komin á dagskrá. Ekkert þar er unnið fyrr en það færist á dagskrá."},{"id":"sprint","g":"team","word":"Sprint","text":"Stutt vinnutörn (oft ein eða tvær vikur) með ákveðnum spjöldum sem á að ljúka.","also":["sprintar","sprinti","sprintum","sprints"]},{"id":"standup","g":"team","word":"Stöðufundur","text":"Stutt yfirferð: hvað hver og einn í teyminu gerði, hvað tekur við og hvað stendur í vegi.","also":["stöðufundir","stöðufundi","stöðufunda","stöðufundar","stand-up","standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Borð með dálkum (Á dagskrá, Í vinnslu, Lokið) þar sem spjöld færast frá vinstri til hægri eftir því sem vinnan gengur."},{"id":"wip","g":"team","word":"WIP-mörk","text":"Verk í vinnslu: flest spjöld sem dálkur á að geyma, svo teymið klári hlutina áður en fleiri eru hafnir.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Fulltrúi","text":"Gervigreind sem vinnur sjálfstætt að verki: les kóðann, gerir breytingar, keyrir athuganir og skilar skýrslu.","also":["fulltrúi","fulltrúa","fulltrúar","fulltrúum","fulltrúann","fulltrúinn","fulltrúans","fulltrúarnir","agent","agents"]},{"id":"token","g":"team","word":"Tákn","text":"Einingin sem gervigreindarnotkun er talin í: nokkrir stafir af texta sem er lesinn eða skrifaður. Færri tákn, meira eftir af áskriftinni.","also":["tákn","tákna","token","tokens"]},{"id":"hook","g":"team","word":"Krókur","text":"Lítil skipun sem keyrir sjálfkrafa á ákveðnu augnabliki, t.d. þegar gervigreindarlota hefst, svo teymið heyri athugasemdir þínar.","also":["krókar","krók","hook","hooks"]}]}};
